node --input-type=module -e "
import { handle } from './src/api.js';
import { dueReminders } from './src/scheduler.js';
const { body: r } = handle({ method: 'POST', path: '/reminders', body: { userId: 'u', text: 't', at: '2026-03-01T09:00', tzOffsetMin: 330 } });
console.log('stored due_ms (UTC):', new Date(r.due_ms).toISOString(), '<- correct: 09:00 IST = 03:30Z');
for (const iso of ['2026-02-28T21:59:00Z','2026-02-28T22:00:00Z','2026-03-01T03:30:00Z']) console.log(iso, 'due?', dueReminders([r], Date.parse(iso)).length === 1);
" && node --test test/ 2>&1 | tail -8
